insert into public.player_position_applicability (position_id, sport_id, discipline_id, variant_id)
select p.id, s.id, d.id, v.id
from seed
join public.player_positions p on p.code = seed.position_code
join public.sports s on s.code = seed.sport_code
left join public.sport_disciplines d on d.sport_id = s.id and d.code = seed.discipline_code
left join public.sport_variants v on v.discipline_id = d.id and v.code = seed.variant_code
where (seed.discipline_code is null or d.id is not null)
  and (seed.variant_code is null or v.id is not null)
on conflict (position_id, sport_id, discipline_id, variant_id) do nothing;

