text, sport_code text, discipline_code text, variant_code text, position_code text) where not exists (select 1 from public.legacy_player_position_mappings m join public.player_positions p on p.id=m.position_id join public.sports s on s.id=m.sport_id left join public.sport_disciplines d on d.id=m.discipline_id left join public.sport_variants v on v.id=m.variant_id where m.source_value=e.source_value and m.normalized_source_value=e.normalized_source_value and s.code=e.sport_code and d.code is not distinct from e.discipline_code and v.code is not distinct from e.variant_code and p.code=e.position_code and m.is_active=true)) then raise exception '5D-C player legacy mapping payload mismatch'; end if;
